static unsigned long g_InvSqrtMantissaTable[128];
static void InitTable()
{
    // entry i: index bit 6 = exponent LSB, bits 0..5 = top mantissa bits; holds the top 8 mantissa bits of 1/sqrt
    for (int i = 0; i < 128; ++i) {
